import { newProject, demoProject, definitions, sections, readiness, nextQuestion, interviewQuestions, generatePrompt, extractTables, validateImport, uid, touch, approve, resolved } from './model.js';
const $ = (s,root=document)=>root.querySelector(s);
const esc = v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='semantic-view-studio-v1';
let projects=[],activeId,route='overview',modelTab='entities',storageError='',contextDraft='',contextTitle='',proposals=[],editing=null,questionEdit=null;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved?.projects){projects=saved.projects.map(raw=>{const clean=validateImport(raw);if(raw.approval&&typeof raw.approval.name==='string'&&typeof raw.approval.at==='string'&&!readiness(clean).issues.some(i=>i.category!=='Review'))clean.approval={name:raw.approval.name,at:raw.approval.at,scope:'Business definitions only; not Snowflake validation'};return clean;});activeId=saved.activeId;}}
catch{storageError='Saved projects could not be loaded. Your stored data has not been overwritten. Export any current work before clearing browser storage.';}
if(!projects.length){const p=newProject();projects=[p];activeId=p.id;}if(!projects.some(p=>p.id===activeId))activeId=projects[0].id;
const project=()=>projects.find(p=>p.id===activeId);
function save(invalidate=true){if(invalidate)touch(project());try{if(storageError.startsWith('Saved projects'))return;localStorage.setItem(KEY,JSON.stringify({projects,activeId}));storageError='';}catch{storageError='Browser storage is full or unavailable. Download a project backup to preserve your work.';}const s=$('#save-state');if(s)s.textContent=storageError?'Backup needed':'Saved on this device';}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
const navs=[['overview','Project brief'],['context','Context library'],['interview','Expert interview'],['model','Semantic model'],['standards','Naming standards'],['validation','Review & readiness'],['export','Cortex Code prompt']];
function go(to){route=navs.some(n=>n[0]===to)?to:'overview';questionEdit=null;render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});}
function field(key,label,value,placeholder='',type='text',full=false){return `<div class="field ${full?'full':''}"><label for="${esc(key)}">${esc(label)}</label>${type==='textarea'?`<textarea id="${esc(key)}" name="${esc(key)}" placeholder="${esc(placeholder)}">${esc(value)}</textarea>`:`<input id="${esc(key)}" name="${esc(key)}" value="${esc(value)}" placeholder="${esc(placeholder)}">`}</div>`;}
const head=(eyebrow,title,desc,action='')=>`<div class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;
function readyCard(){const r=readiness(project());return `<div class="card"><p class="eyebrow">Specification readiness</p><h2>${r.ready?'Ready for handoff':'Build a grounded model'}</h2><div class="readiness-number">${r.score}%<span>of checkpoints complete</span></div><div class="progress" role="progressbar" aria-label="Specification readiness" aria-valuenow="${r.score}" aria-valuemin="0" aria-valuemax="100"><div style="width:${r.score}%"></div></div><ul class="checklist">${r.checks.map(c=>`<li><span class="checkmark ${c.done?'done':''}">${c.done?'✓':'·'}</span>${c.label}</li>`).join('')}</ul><div class="callout"><strong>${r.ready?'Business definitions approved':'Accuracy starts with context'}</strong>${r.ready?'Cortex Code must still verify source mappings and test results in Snowflake.':'Unresolved definitions stay visible. Your prompt will ask Cortex Code to investigate before creating a view.'}</div><div class="gap"><button class="link" data-go="validation">View readiness checks</button></div></div>`;}
function render(){const p=project();const r=readiness(p);$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-icon" aria-hidden="true">≋</div><div>Semantic<br> View Studio</div></div><p class="eyebrow">Your workspace</p><nav aria-label="Modeling workflow">${navs.map(([id,label],i)=>`<button class="nav-button ${route===id?'active':''}" data-go="${id}" ${route===id?'aria-current="page"':''}><span class="nav-number">0${i+1}</span>${label}${id==='export'?'<span class="nav-badge">↗</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-label"><strong>Knowledge stays on this device</strong>Projects are saved in this browser. Export a backup to move your work.</div><button data-action="new">+ New project</button><button data-action="example">Explore an example</button></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb">Workspace <span aria-hidden="true"> / </span> <b>${esc(p.name)}</b></div><div class="top-actions"><span class="saved"><i></i><span id="save-state">${storageError?'Backup needed':'Saved on this device'}</span></span><button data-action="projects">Projects</button><button data-go="export" class="primary">Export prompt</button></div></header><main id="main" tabindex="-1">${storageError?`<div class="callout warn">${esc(storageError)} <button data-action="backup" class="small">Download backup</button></div>`:''}${pages[route]()}</main></div></div>`;bind();}
const pages={
 overview(){const p=project();return head('01 / Project brief','From expert knowledge to business meaning.','Define the questions your semantic view should answer. We’ll help you turn the details into a precise Cortex Code handoff.',`<span class="pill ${p.approval?'green':''}">${p.approval?'SME approved':'Draft specification'}</span>`)+`<div class="grid"><div><form id="brief-form" class="card"><div class="card-header"><div><h2>Start with the business question</h2><p class="muted">A focused purpose makes every definition easier to get right.</p></div><span class="pill">01</span></div><div class="form-grid">${field('name','Project name',p.name,'Sales performance')}${field('domain','Business domain',p.domain,'Sales & revenue')}${field('owner','Domain owner / subject matter expert',p.owner,'Name or team','text',true)}${field('purpose','What should this view help people decide?',p.purpose,'Describe the audience, business decisions, and intended use.','textarea',true)}${field('questions','Questions it should answer',p.questions,'What was net revenue by region last month?\nWhich customer segments grew fastest?','textarea',true)}${field('exclusions','What is out of scope?',p.exclusions,'Forecasts, test transactions, and canceled orders…','textarea',true)}</div><div class="card-foot"><p class="tip">You can refine these answers during the interview.</p><button type="button" class="primary" data-go="interview">Start interview</button></div></form><form id="target-form" class="card"><div class="card-header"><div><h2>Snowflake destination</h2><p class="muted">Cortex Code will verify this execution context before creating anything.</p></div></div><div class="form-grid">${field('target','Fully qualified semantic view name',p.target,'ANALYTICS.SEMANTIC.SV_SALES_PERFORMANCE','text',true)}${field('role','Execution role',p.role,'SEMANTIC_DEVELOPER')}${field('warehouse','Warehouse',p.warehouse,'ANALYTICS_WH')}<div class="field"><label for="environment">Environment</label><select name="environment" id="environment">${['Development','Test','Production'].map(x=>`<option ${p.environment===x?'selected':''}>${x}</option>`).join('')}</select></div>${field('updatePolicy','Existing target policy',p.updatePolicy,'','textarea',true)}</div></form></div><aside class="aside">${readyCard()}<div class="card"><p class="eyebrow">A practical path</p><h2>Your expertise, structured.</h2><div class="step-list"><div class="step-item"><span class="step-icon">1</span><div><b>Bring what you know</b>Use documents, source DDL, or an interview.</div></div><div class="step-item"><span class="step-icon">2</span><div><b>Resolve what matters</b>Review grain, formulas, joins, and exceptions.</div></div><div class="step-item"><span class="step-icon">3</span><div><b>Hand off with confidence</b>Export a prompt with definitions and explicit checks.</div></div></div><div class="card-foot"><button class="link" data-action="example">Explore the sales example</button></div></div></aside></div>`;},
 context(){const p=project();return head('02 / Context library','Give your model a source of truth.','Add glossaries, metric definitions, or source DDL. Context is retained as evidence; extracted mappings remain proposals until you review them.')+`<div class="grid"><div><div class="card"><div class="card-header"><div><h2>Add supporting context</h2><p class="muted">Paste text or import a plain-text document.</p></div><button data-action="upload-context" class="small">Import file</button></div><div class="field"><label for="context-title">Source title</label><input id="context-title" value="${esc(contextTitle)}" placeholder="Sales data dictionary · October 2026"></div><div class="field gap"><label for="context-text">Context or CREATE TABLE statements</label><textarea id="context-text" class="context-area" placeholder="Paste business definitions, reference queries, or CREATE TABLE statements here. Physical identifiers are preserved exactly.">${esc(contextDraft)}</textarea></div><div class="card-foot"><p class="tip">TXT, MD, SQL, CSV, JSON, or YAML · up to 1 MB</p><div class="actions"><button data-action="extract">Extract table mappings</button><button data-action="save-context" class="primary">Save context</button></div></div><p class="footer-note">Schema extraction recognizes CREATE TABLE statements. Prose is retained verbatim for review; this version does not infer business rules with AI.</p></div>${proposals.length?`<div class="card"><div class="card-header"><div><h2>${proposals.length} proposed mapping${proposals.length===1?'':'s'}</h2><p class="muted">Grain and business meaning still need your expertise.</p></div><button class="primary small" data-action="accept-proposals">Add to model</button></div>${proposals.map(e=>`<div class="model-row"><h3>${esc(e.name)}</h3><code>${esc(e.source)}</code><p class="row-description">${esc(e.columns)}</p><span class="pill amber">Proposed · not verified</span></div>`).join('')}</div>`:''}<div class="section-label"><h2>Evidence library</h2><span class="pill">${p.evidence.length} sources</span></div><div class="card">${p.evidence.length?p.evidence.map(e=>`<div class="evidence"><div class="row-title"><h3>${esc(e.title)}</h3><button class="link danger" data-delete-evidence="${esc(e.id)}">Remove</button></div><pre>${esc(e.text)}</pre><span class="record-meta">Added ${esc(new Date(e.at).toLocaleDateString())} · Reference material</span></div>`).join(''):`<div class="empty"><h3>No context added yet</h3><p>Start with a data dictionary or an existing reporting query.<br>You can also build your model entirely through the interview.</p></div>`}</div></div><aside class="aside">${readyCard()}<div class="card"><h2>What makes useful context?</h2><div class="step-list"><div class="step-item"><span class="step-icon">≡</span><div><b>Business definitions</b>Formulas, exclusions, terms, and examples.</div></div><div class="step-item"><span class="step-icon">⌘</span><div><b>Source structure</b>Fully qualified tables, column types, and declared keys.</div></div><div class="step-item"><span class="step-icon">✓</span><div><b>Expected results</b>Trusted reports or independently checked queries.</div></div></div><p class="footer-note">Everything is stored in this browser. Context is included in your exported prompt.</p></div></aside></div>`;},
 interview(){const p=project();const q=questionEdit?interviewQuestions.find(q=>q.key===questionEdit):nextQuestion(p);const done=interviewQuestions.filter(q=>resolved(p[q.key])).length;return head('03 / Expert interview','Let’s make the implicit explicit.','A guided interview follows the gaps in your specification. Answers you already supplied are skipped; uncertainty stays visible.',`<span class="pill green">${done} of ${interviewQuestions.length} topics covered</span>`)+`<div class="grid"><div>${q?`<div class="card question-card"><div class="question-meta"><span class="pill green">${esc(q.label)}</span><span>Business definition</span></div><h2>${esc(q.question)}</h2><p class="muted">${esc(q.help)}</p>${q.options?`<div class="question-options">${q.options.map(o=>`<button data-answer-option="${esc(o)}">${esc(o)}</button>`).join('')}</div>`:''}<label class="hidden" for="answer">Your answer</label><textarea id="answer" placeholder="${esc(q.placeholder)}">${esc(p[q.key]||'')}</textarea><div class="card-foot"><button class="link" data-action="defer" data-key="${q.key}">I don’t know yet</button><button class="primary" data-action="answer" data-key="${q.key}">Save answer & continue</button></div></div>`:`<div class="card question-card"><span class="pill ${done===interviewQuestions.length?'green':'amber'}">${done===interviewQuestions.length?'Business context captured':'Interview paused on open questions'}</span><h2>${done===interviewQuestions.length?'Your business rules are taking shape.':'Some definitions need a second opinion.'}</h2><p class="muted">${done===interviewQuestions.length?'Next, translate the definitions into entities, dimensions, and metrics. The model editor tracks the technical details.':'Revisit the unresolved topics below when the right expert is available. You can continue building your model now.'}</p><div class="actions gap"><button class="primary" data-go="model">Open semantic model</button>${p.deferred.length?'<button data-action="revisit">Revisit open questions</button>':''}</div></div>`}<div class="section-label"><h2>Business definitions</h2><span class="pill">Editable at any time</span></div><div class="card">${interviewQuestions.filter(q=>p[q.key]||p.deferred.includes(q.key)).map(q=>`<div class="history-row"><div class="row-title"><h3>${esc(q.label)}</h3><button class="link" data-edit-question="${q.key}">Edit</button></div><p>${esc(p[q.key]||'Awaiting expert input.')}</p><span class="pill ${resolved(p[q.key])?'green':'amber'}">${resolved(p[q.key])?'Captured':'Unresolved'}</span></div>`).join('')||'<p class="muted">Your answers will appear here as the interview progresses.</p>'}</div></div><aside class="aside">${readyCard()}<div class="card"><h2>Precision over guesswork</h2><p class="muted">If an answer depends on another team, defer it. Missing answers are carried into the discovery prompt so Cortex Code can help investigate.</p><p class="tip">This is a rule-based interview. It does not claim to have checked your answers against source data.</p></div></aside></div>`;},
 model(){const p=project();const def=definitions[modelTab];return head('04 / Semantic model','Make every definition reviewable.','Connect business language to physical data. These are proposed definitions until the entire specification is reviewed.')+`<div class="stat-row"><div class="stat"><strong>${p.entities.length}</strong><span>Business entities</span></div><div class="stat"><strong>${p.metrics.length}</strong><span>Defined metrics</span></div><div class="stat"><strong>${p.decisions.filter(d=>!resolved(d.resolution)).length}</strong><span>Open decisions</span></div></div><div class="tabs" role="tablist" aria-label="Model components">${sections.map(s=>`<button role="tab" aria-selected="${modelTab===s}" class="${modelTab===s?'active':''}" data-model-tab="${s}">${({entities:'Entities',relationships:'Relationships',dimensions:'Dimensions & facts',metrics:'Metrics',evaluations:'Evaluations',decisions:'Decisions'})[s]} <span class="nav-number">${p[s].length}</span></button>`).join('')}</div><div class="card"><div class="card-header"><div><h2>${esc(def.singular)} definitions</h2><p class="muted">${esc(def.description)}</p></div><button class="primary" data-action="add-record">+ Add ${esc(def.singular.toLowerCase())}</button></div>${p[modelTab].length?p[modelTab].map(r=>recordCard(r)).join(''):`<div class="empty"><h3>No ${esc(def.singular.toLowerCase())} definitions yet</h3><p>${esc(def.description)}</p><button data-action="add-record">Add the first definition</button></div>`}</div><div class="callout"><strong>Business meaning and data validity are separate.</strong>Source mappings and expressions are user-supplied. Cortex Code must inspect metadata, profile joins, and test calculations in Snowflake.</div>`;},
 standards(){const p=project();return head('05 / Naming standards','A shared language, consistently applied.','Set your team’s policy for semantic names. Physical Snowflake identifiers are always preserved exactly.')+`<div class="grid"><div><form id="naming-form" class="card"><div class="card-header"><div><h2>Your naming policy</h2><p class="muted">Defaults are a proposed team convention, not a Snowflake requirement.</p></div></div><div class="form-grid">${field('prefix','Semantic view prefix',p.naming.prefix,'SV_')}<div class="field"><label for="style">Logical identifier style</label><select id="style" name="style"><option ${p.naming.style==='snake_case'?'selected':''}>snake_case</option><option ${p.naming.style==='UPPER_SNAKE_CASE'?'selected':''}>UPPER_SNAKE_CASE</option></select></div>${field('abbreviations','Approved abbreviations',p.naming.abbreviations,'id, usd, utc','text',true)}${field('naming-exceptions','Documented exceptions / additional conventions',p.naming.exceptions,'Record intentional exceptions for Cortex Code to review. These do not suppress local validation.','textarea',true)}</div></form><div class="card"><h2>Recommended vocabulary</h2><div class="review-summary"><div><b>Identifiers</b><code>customer_id</code><br><span>Use the business entity and _id.</span></div><div><b>Time fields</b><code>order_date</code><br><span>Distinguish dates from timestamps.</span></div><div><b>Amounts</b><code>net_revenue_usd</code><br><span>Make business meaning and units clear.</span></div><div><b>Ratios</b><code>gross_margin_ratio</code><br><span>Document whether the scale is 0–1 or 0–100.</span></div><div><b>Booleans</b><code>is_canceled</code><br><span>Use is_ or has_ for conditions.</span></div><div><b>Counts</b><code>order_count</code><br><span>Specify what is actually counted.</span></div></div><p class="tip">Local checks enforce identifier style, reserved words, view prefixes, duplicate names, and synonym collisions. Abbreviations, suffix semantics, and exceptions are reviewed by the SME and included in the prompt.</p></div></div><aside class="aside">${readyCard()}</aside></div>`;},
 validation(){const p=project();const r=readiness(p);const blocking=r.issues.filter(i=>i.category!=='Review');return head('06 / Review & readiness','Confidence comes from explicit checks.','Resolve the gaps, review the business definitions, and approve the handoff. Source validity and analytical results will still need Snowflake verification.',`<span class="pill ${r.ready?'green':'amber'}">${r.ready?'Creation prompt available':`${r.issues.length} open checks`}</span>`)+`<div class="grid"><div><div class="card"><div class="card-header"><div><h2>Specification checks</h2><p class="muted">These checks run locally against the current specification.</p></div></div>${r.issues.length?r.issues.map(i=>`<div class="issue"><span class="issue-icon">!</span><div><h3>${esc(i.title)}</h3><p>${esc(i.detail)}</p><span class="record-meta">${esc(i.category)}</span></div>${i.category==='Review'?'':`<button class="small" data-go="${i.route}">Resolve</button>`}</div>`).join(''):'<div class="empty"><h3>All specification checks passed</h3><p>Business definitions are approved. The creation prompt still requires Cortex Code to verify and test the view.</p></div>'}</div><div class="card ${p.approval?'approval':''}"><h2>SME approval</h2><p class="muted">Confirm that the definitions reflect the intended business meaning. Editing the specification automatically clears this approval.</p>${p.approval?`<p><span class="pill green">Approved by ${esc(p.approval.name)}</span></p><p class="tip">${esc(new Date(p.approval.at).toLocaleString())} · Business definitions only</p><button data-action="revoke">Reopen for review</button>`:`<div class="field"><label for="reviewer">Reviewer name</label><input id="reviewer" placeholder="Subject matter expert’s name" value="${esc(p.owner)}"></div><label class="checkbox gap"><input id="approve-check" type="checkbox" ${blocking.length?'disabled':''}><span>I reviewed the business scope, source mappings, metrics, time rules, and expected behaviors. These reflect our intended definitions.</span></label><div class="card-foot"><p class="tip">${blocking.length?`Resolve ${blocking.length} other checks to enable approval.`:'All prerequisites passed. Business approval will enable a creation prompt.'}</p><button class="green" data-action="approve" ${blocking.length?'disabled':''}>Approve specification</button></div>`}</div><div class="card"><h2>Checks to run in Snowflake</h2><ul class="checklist">${['Source objects, columns, and permissions exist','Declared keys are unique and non-null','Joins preserve grain and avoid fanout','Metric results reconcile to reference queries','Edge cases and comparison tolerances pass','Existing access policies remain effective'].map(s=>`<li><span class="checkmark">·</span>${s}</li>`).join('')}</ul><p class="footer-note">Not run by this app. The exported prompt requires Cortex Code to report observed results.</p></div></div><aside class="aside">${readyCard()}</aside></div>`;},
 export(){const p=project();const r=readiness(p);const prompt=generatePrompt(p);return head('07 / Cortex Code handoff','Your expertise, ready for the next step.','Copy this self-contained prompt into Snowflake Cortex Code. It includes the current specification, supporting evidence, and validation requirements.',`<span class="pill ${r.ready?'green':'amber'}">${r.ready?'Creation prompt':'Discovery prompt'}</span>`)+`<div class="grid"><div><div class="card"><div class="card-header"><div><h2>${r.ready?'Create after verification':'Investigate before creation'}</h2><p class="muted">${prompt.length.toLocaleString()} characters · Full specification included</p></div><div class="actions"><button data-action="download-prompt">Download .md</button><button class="primary" data-action="copy-prompt">Copy prompt</button></div></div><pre class="prompt" id="prompt-text" tabindex="0">${esc(prompt)}</pre></div></div><aside class="aside"><div class="card"><p class="eyebrow">Handoff status</p><h2>${r.ready?'Business-ready, not yet data-tested':'Discovery comes first'}</h2><p class="muted">${r.ready?'The prompt authorizes creation in your specified environment after Cortex Code verifies the source data and prerequisites.':`There are ${r.issues.length} open specification checks. This prompt asks Cortex Code to investigate and return findings without creating the view.`}</p><div class="review-summary"><div><b>Target</b><span>${esc(p.target||'Not specified')}</span></div><div><b>Environment</b><span>${esc(p.environment)}</span></div></div><button data-go="validation">Review open checks</button><div class="callout"><strong>Use a Snowflake-connected session</strong>Cortex Code needs access to the specified sources, role, warehouse, and target schema.</div></div><div class="card"><h2>Keep a portable copy</h2><p class="muted">A project backup preserves your evidence, interview, and editable definitions. Imported projects require a fresh review.</p><button data-action="backup">Download project JSON</button><p class="footer-note">No credentials or live Snowflake connection are configured in this app.</p></div></aside></div>`;}
};
function recordCard(r){const type=modelTab;let detail=r.description||r.expected||'';const expression=r.expression||r.source||(type==='relationships'?`${r.from} (${r.fromColumns}) → ${r.to} (${r.toColumns})`:r.question||r.resolution||'');return `<article class="model-row"><div class="row-title"><div><h3>${esc(r.name||'Untitled definition')}</h3><span class="pill ${project().approval?'green':'amber'}">${project().approval?'SME confirmed':'Proposed'}</span></div><div class="actions"><button class="small" data-edit-record="${esc(r.id)}">Edit</button><button class="small danger" data-delete-record="${esc(r.id)}">Remove</button></div></div>${expression?`<code class="code-line">${esc(expression)}</code>`:''}<p class="row-description">${esc(detail)}</p><div class="record-meta">${r.grain?`<span class="source-chip">${esc(r.grain)}</span>`:''}${r.units?`<span class="source-chip">${esc(r.units)}</span>`:''}${r.cardinality?`<span class="source-chip">${esc(r.cardinality)}</span>`:''}<span>Source: ${esc(r.evidence||'Not recorded')}</span></div></article>`;}
function download(name,text,type){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const fileStem=()=>project().name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'semantic-view';
function addProject(p){projects.push(p);activeId=p.id;contextDraft='';contextTitle='';proposals=[];save(false);go('overview');}
function openDialog(title,body,foot){const dialog=$('#editor');dialog.innerHTML=`<form id="dialog-form"><div class="dialog-head"><h2>${esc(title)}</h2><button type="button" class="link" data-close aria-label="Close dialog">✕</button></div><div class="dialog-body"><p id="dialog-error" class="error-text" role="alert"></p>${body}</div><div class="dialog-foot">${foot}</div></form>`;dialog.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>dialog.close()));dialog.showModal();}
function editRecord(id){const def=definitions[modelTab];const record=project()[modelTab].find(r=>r.id===id)||{};editing={section:modelTab,id};openDialog(`${id?'Edit':'Add'} ${def.singular.toLowerCase()}`,`<p class="muted">${esc(def.description)}</p><div class="form-grid">${def.fields.map(([key,label,type,placeholder])=>{if(type==='entity'||type==='select'){const opts=type==='entity'?project().entities.map(e=>e.name):placeholder;return `<div class="field"><label for="record-${key}">${esc(label)}</label><select id="record-${key}" name="${key}">${type==='entity'?'<option value="">Choose an entity</option>':''}${opts.map(o=>`<option value="${esc(o)}" ${record[key]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;}return field(key,label,record[key]||'',placeholder,type,type==='textarea');}).join('')}</div>`,`<button type="button" data-close>Cancel</button><button type="submit" class="primary">Save definition</button>`);$('#dialog-form').addEventListener('submit',event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.currentTarget));if(!values.name.trim()){$('#dialog-error').textContent='Give this definition a name.';return;}const section=editing.section;const updated={id:editing.id||uid(),...values,status:'proposed'};const index=project()[section].findIndex(r=>r.id===editing.id);if(index<0)project()[section].push(updated);else project()[section][index]=updated;save();$('#editor').close();render();toast('Definition saved. Readiness checks updated.');});}
function confirmDelete(title,description,onConfirm){openDialog(title,`<p class="muted">${esc(description)}</p>`,`<button type="button" data-close>Cancel</button><button type="submit" class="danger">Remove</button>`);$('#dialog-form').addEventListener('submit',e=>{e.preventDefault();onConfirm();$('#editor').close();save();render();});}
function projectsDialog(){openDialog('Your projects',`<div>${projects.map(p=>`<div class="model-row"><div class="row-title"><div><h3>${esc(p.name)}</h3><p class="muted">${esc(p.domain||'Domain not set')}${p.id===activeId?' · Current project':''}</p></div><button type="button" data-open-project="${esc(p.id)}">Open</button></div></div>`).join('')}</div>`,`<button type="button" id="import-project">Import JSON</button><button type="button" id="new-project" class="primary">New project</button>`);document.querySelectorAll('[data-open-project]').forEach(b=>b.onclick=()=>{activeId=b.dataset.openProject;contextDraft='';contextTitle='';proposals=[];save(false);$('#editor').close();go('overview');});$('#import-project').onclick=()=>$('#import-file').click();$('#new-project').onclick=()=>{$('#editor').close();addProject(newProject());};}
function saveContext(){const title=contextTitle.trim(),text=contextDraft.trim();if(!title||!text){toast('Add a source title and context first.');return false;}if(text.length>1000000){toast('Keep each source under 1 MB.');return false;}const exists=project().evidence.some(e=>e.title===title&&e.text===text);if(!exists)project().evidence.push({id:uid(),title,text,at:new Date().toISOString()});save();return true;}
function bind(){
 document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
 const refreshReadiness=()=>{const aside=$('.aside');if(aside?.firstElementChild)aside.firstElementChild.outerHTML=readyCard();document.querySelectorAll('.aside [data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));const crumb=$('.breadcrumb b');if(crumb)crumb.textContent=project().name;};
 for(const id of ['brief-form','target-form']){const form=$('#'+id);if(form){form.onsubmit=e=>e.preventDefault();form.addEventListener('input',e=>{if(e.target.name){project()[e.target.name]=e.target.value;save();refreshReadiness();}});}}
 const naming=$('#naming-form');if(naming){naming.onsubmit=e=>e.preventDefault();naming.oninput=e=>{project().naming[e.target.name==='naming-exceptions'?'exceptions':e.target.name]=e.target.value;save();refreshReadiness();};}
 document.querySelectorAll('[data-model-tab]').forEach(b=>b.onclick=()=>{modelTab=b.dataset.modelTab;render();});
 document.querySelectorAll('[data-edit-record]').forEach(b=>b.onclick=()=>editRecord(b.dataset.editRecord));
 document.querySelectorAll('[data-delete-record]').forEach(b=>b.onclick=()=>confirmDelete('Remove definition?','Dependent definitions will be preserved and any broken references will appear in readiness checks.',()=>{project()[modelTab]=project()[modelTab].filter(r=>r.id!==b.dataset.deleteRecord);}));
 document.querySelectorAll('[data-delete-evidence]').forEach(b=>b.onclick=()=>confirmDelete('Remove this source?','Definitions remain, but their evidence references may need updating.',()=>{const removed=project().evidence.find(e=>e.id===b.dataset.deleteEvidence);project().evidence=project().evidence.filter(e=>e.id!==b.dataset.deleteEvidence);if(removed)for(const s of sections)for(const rec of project()[s])if(rec.evidence===removed.title)rec.evidence='';}));
 document.querySelectorAll('[data-edit-question]').forEach(b=>b.onclick=()=>{questionEdit=b.dataset.editQuestion;render();window.scrollTo(0,0);$('#answer')?.focus();});
 document.querySelectorAll('[data-answer-option]').forEach(b=>b.onclick=()=>{$('#answer').value=b.dataset.answerOption;$('#answer').focus();});
 if($('#context-title'))$('#context-title').oninput=e=>contextTitle=e.target.value;
 if($('#context-text'))$('#context-text').oninput=e=>contextDraft=e.target.value;
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actions[b.dataset.action]?.(b));
}
const actions={
 new:()=>addProject(newProject()),example:()=>{addProject(demoProject());toast('Example project added. Replace sample definitions before using it.');},projects:projectsDialog,
 'add-record':()=>editRecord(),
 'upload-context':()=>$('#context-file').click(),
 'save-context':()=>{if(saveContext()){contextDraft='';contextTitle='';proposals=[];render();toast('Source saved to your evidence library.');}},
 extract:()=>{if(!contextDraft.trim()){toast('Paste CREATE TABLE statements first.');return;}proposals=extractTables(contextDraft,contextTitle.trim()||'Imported schema');if(!proposals.length)toast('No supported CREATE TABLE statements found. Save prose as context and add mappings manually.');render();},
 'accept-proposals':()=>{if(!saveContext())return;const existing=new Set(project().entities.map(e=>e.source));let count=0;for(const proposed of proposals)if(!existing.has(proposed.source)){project().entities.push({...proposed,evidence:contextTitle.trim()});existing.add(proposed.source);count++;}save();proposals=[];contextDraft='';contextTitle='';render();toast(`${count} proposed mapping${count===1?'':'s'} added. Complete grain and business meaning in the model.`);},
 answer:b=>{const q=interviewQuestions.find(q=>q.key===b.dataset.key);const answer=$('#answer').value.trim();if(!answer){toast('Enter an answer or choose “I don’t know yet.”');return;}project()[q.key]=answer;project().answers.push({key:q.key,question:q.question,answer,at:new Date().toISOString()});project().deferred=project().deferred.filter(k=>k!==q.key);if(!resolved(answer))project().deferred.push(q.key);questionEdit=null;save();render();toast(resolved(answer)?'Answer saved to your specification.':'Saved as unresolved.');},
 defer:b=>{const key=b.dataset.key;if(!project().deferred.includes(key))project().deferred.push(key);project()[key]='';questionEdit=null;save();render();toast('Left open for follow-up.');},
 revisit:()=>{project().deferred=[];save();render();},
 approve:()=>{if(!$('#approve-check')?.checked){toast('Confirm that you have reviewed the definitions.');return;}try{approve(project(),$('#reviewer').value);save(false);render();toast('Business definitions approved. Creation prompt is available.');}catch(e){toast(e.message);}},
 revoke:()=>{save();render();toast('Specification reopened for review.');},
 backup:()=>{download(`${fileStem()}.json`,JSON.stringify(project(),null,2),'application/json');toast('Project backup downloaded.');},
 'download-prompt':()=>{download(`${fileStem()}-cortex-prompt.md`,generatePrompt(project()),'text/markdown');toast('Cortex Code prompt downloaded.');},
 'copy-prompt':async()=>{try{await navigator.clipboard.writeText(generatePrompt(project()));toast('Prompt copied. Paste it into Snowflake Cortex Code.');}catch{const node=$('#prompt-text');const range=document.createRange();range.selectNodeContents(node);const sel=window.getSelection();sel.removeAllRanges();sel.addRange(range);toast('Clipboard unavailable. Prompt selected; press Ctrl+C or download it.');}}
};
$('#context-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>1000000){toast('Choose a text file under 1 MB.');return;}if(!/\.(txt|md|sql|csv|json|ya?ml)$/i.test(file.name)){toast('Use TXT, MD, SQL, CSV, JSON, or YAML.');return;}try{contextDraft=await file.text();contextTitle=file.name;go('context');toast('File loaded. Review it, then save or extract mappings.');}catch{toast('Could not read this file. Try pasting the text.');}});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>5000000){toast('Choose a project backup under 5 MB.');return;}try{const p=validateImport(JSON.parse(await file.text()));p.id=uid();p.name+=' (imported)';$('#editor').close();addProject(p);toast('Project imported. A fresh SME review is required.');}catch(error){toast(`Import failed: ${error.message}`);}});
render();
// Optional browser-agent access uses the same specification as the UI.
const modelContext=document.modelContext;
if(modelContext?.registerTool){const life=new AbortController();const register=tool=>{try{Promise.resolve(modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{});}catch{}};
 register({name:'read_semantic_specification',description:'Read the current project specification and its readiness checks.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('Expected an empty object.');return{specification:JSON.parse(JSON.stringify(project())),readiness:readiness(project())};}});
 register({name:'read_cortex_code_prompt',description:'Return the current discovery or creation prompt without creating anything in Snowflake.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('Expected an empty object.');return{mode:readiness(project()).ready?'creation':'discovery',prompt:generatePrompt(project())};}});
 window.addEventListener('pagehide',()=>life.abort(),{once:true});
}
